package com.aistock.scheduler.admin;
import com.aistock.common.BusinessException;import com.fasterxml.jackson.databind.ObjectMapper;import java.sql.Timestamp;import java.time.*;import java.util.*;
import org.flywaydb.core.Flyway;import org.junit.jupiter.api.*;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.jdbc.datasource.DriverManagerDataSource;
import static org.junit.jupiter.api.Assertions.*;import static com.aistock.scheduler.admin.AdminTaskRecords.*;
@Tag("mysql") class AdminTaskMysqlTest {
 JdbcTemplate jdbc;AdminTaskService service;final Instant now=Instant.parse("2026-10-20T12:00:00Z");
 @BeforeEach void setup(){var url=System.getenv("SCHEDULER_TEST_DB_URL");var secret=System.getenv("SCHEDULER_TEST_DB_PASSWORD");if(!"jdbc:mysql://127.0.0.1:13316/stock_scheduler_test?serverTimezone=UTC".equals(url)||secret==null||secret.isBlank())throw new IllegalStateException("Only isolated scheduler DB allowed");var ds=new DriverManagerDataSource(url,"root",secret);Flyway.configure().dataSource(ds).locations("classpath:db/migration").load().migrate();jdbc=new JdbcTemplate(ds);assertEquals("stock_scheduler_test",jdbc.queryForObject("select database()",String.class));jdbc.update("delete from comparison_update_context");jdbc.update("delete from task_attempt");jdbc.update("delete from admin_market_refresh_operation" );jdbc.update("delete from admin_market_refresh_guard" );jdbc.update("delete from admin_market_refresh_context" );jdbc.update("delete from scheduled_task");service=new AdminTaskService(new AdminTaskRepository(jdbc),new AdminTaskCursorCodec(),Clock.fixed(now,ZoneOffset.UTC));}
 String id(int i){return String.format("00000000-0000-0000-0000-%012d",i);}
 void task(int i,String type,String state,Instant time){jdbc.update("insert into scheduled_task(task_id,task_type,instrument_id,target_date,idempotency_key,state,attempt_count,next_at,created_at,updated_at,prediction_id,rule_version) values(?,?,?,'2026-10-20',?,?,0,?,?,?,?,?)",id(i),type,"SH600030","test-"+i,state,Timestamp.from(time),Timestamp.from(time),Timestamp.from(time),type.equals("PREDICTION_VERIFY")?id(999):null,type.equals("PREDICTION_VERIFY")?"origin-share-close-v1":null);}
 void attempt(int task,int ordinal,Instant end){jdbc.update("insert into task_attempt(attempt_id,task_id,ordinal,state,started_at,lease_until,finished_at,error_code) values(?,?,?,'FAILED',?,?,?,'SOURCE_TIMEOUT')",UUID.randomUUID().toString(),id(task),ordinal,Timestamp.from(now),Timestamp.from(now.plusSeconds(90)),end==null?null:Timestamp.from(end));}
 TaskQuery q(int limit){return new TaskQuery(null,null,null,LocalDate.of(2026,10,1),LocalDate.of(2026,10,20),limit);}
 @Test void sameMillisecondPagesExcludeNewerInsertsAndNeverDuplicate(){for(int i=1;i<=3;i++)task(i,"MARKET_REFRESH","QUEUED",now);var a=service.list(q(2),null);assertEquals(List.of(id(3),id(2)),a.items().stream().map(TaskSummary::taskId).toList());task(4,"MARKET_REFRESH","QUEUED",now.plusMillis(1));var b=service.list(q(2),a.nextCursor());assertEquals(List.of(id(1)),b.items().stream().map(TaskSummary::taskId).toList());assertFalse(b.hasMore());assertNull(b.nextCursor());}
 @Test void liveStateChangesAreNotFrozen(){task(1,"MARKET_REFRESH","QUEUED",now);task(2,"MARKET_REFRESH","QUEUED",now);var a=service.list(q(1),null);jdbc.update("update scheduled_task set state='FAILED' where task_id=?",id(1));var b=service.list(q(1),a.nextCursor());assertEquals("FAILED",b.items().get(0).state());}
 @Test void typesStatesAndShanghaiBoundaryFilter(){task(1,"MARKET_REFRESH","FAILED",Instant.parse("2026-09-30T15:59:59.999Z"));task(2,"PREDICTION_VERIFY","SKIPPED",Instant.parse("2026-09-30T16:00:00Z"));task(3,"COMPARISON_UPDATE","SUCCEEDED",now);assertEquals(2,service.list(q(20),null).items().size());var query=new TaskQuery("PREDICTION_VERIFY","SKIPPED","SH600030",q(20).createdFrom(),q(20).createdTo(),20);assertEquals(List.of(id(2)),service.list(query,null).items().stream().map(TaskSummary::taskId).toList());assertTrue(service.list(new TaskQuery(null,null,"SZ000002",q(20).createdFrom(),q(20).createdTo(),20),null).items().isEmpty());}
 @Test void attemptsOver100KeepOriginalOrdinalsAndSeparateCycleCount(){task(1,"MARKET_REFRESH","QUEUED",now);for(int n=1;n<=110;n++)attempt(1,n,now.plusMillis(n));var detail=service.detail(id(1));assertEquals(110,detail.task().summary().totalAttempts());assertEquals(0,detail.task().cycleAttempts());var seen=new ArrayList<Integer>();String cursor=null;do{var page=service.attempts(id(1),new AttemptQuery(20),cursor);seen.addAll(page.items().stream().map(Attempt::ordinal).toList());cursor=page.nextCursor();}while(cursor!=null);assertEquals(110,seen.size());assertEquals(110,seen.get(109));assertEquals(110,service.list(q(20),null).items().get(0).totalAttempts());}
 @Test void attemptUpperBoundOnlyExtendsAfterRefresh(){task(1,"MARKET_REFRESH","QUEUED",now);attempt(1,1,now.plusSeconds(1));attempt(1,2,now.plusSeconds(2));var first=service.attempts(id(1),new AttemptQuery(1),null);attempt(1,3,now.plusSeconds(3));var second=service.attempts(id(1),new AttemptQuery(1),first.nextCursor());assertEquals(2,second.items().get(0).ordinal());assertFalse(second.hasMore());assertEquals(3,service.attempts(id(1),new AttemptQuery(20),null).items().size());}
 @Test void durationNeverInventedAndPrivateFieldsAreAbsent()throws Exception{task(1,"MARKET_REFRESH","QUEUED",now);attempt(1,1,now.minusMillis(1));attempt(1,2,null);attempt(1,3,now.plusMillis(321));var p=service.attempts(id(1),new AttemptQuery(20),null);assertNull(p.items().get(0).durationMillis());assertTrue(p.items().get(0).reason().message().contains("时间"));assertNull(p.items().get(1).durationMillis());assertEquals(321L,p.items().get(2).durationMillis());var json=new ObjectMapper().findAndRegisterModules().writeValueAsString(List.of(service.detail(id(1)),p));for(var secret:List.of("attempt_id","attemptId","currentAttempt","idempotency","leaseUntil","test-1"))assertFalse(json.contains(secret));}
 @Test void queryDoesNotModifyRows(){task(1,"MARKET_REFRESH","RECONCILING",now);attempt(1,1,now.plusMillis(5));var before=jdbc.queryForList("select * from scheduled_task");var attempts=jdbc.queryForList("select * from task_attempt");service.list(q(20),null);service.detail(id(1));service.attempts(id(1),new AttemptQuery(20),null);assertEquals(before,jdbc.queryForList("select * from scheduled_task"));assertEquals(attempts,jdbc.queryForList("select * from task_attempt"));}
 @Test void missingTaskAndIndexes(){assertEquals("TASK_NOT_FOUND",assertThrows(BusinessException.class,()->service.detail(id(1))).code());assertThrows(BusinessException.class,()->service.attempts(id(1),new AttemptQuery(20),null));assertTrue(jdbc.queryForList("show index from scheduled_task").stream().anyMatch(x->"ix_task_created_id".equals(x.get("Key_name"))));assertFalse(jdbc.queryForList("explain select task_id from scheduled_task where created_at>=? and created_at<? order by created_at desc,task_id desc limit 21",Timestamp.from(now.minusSeconds(10)),Timestamp.from(now.plusSeconds(10))).isEmpty());}
}
